// Plays every unplayed match dated on or before "simulateUpTo" (set in Simulation Settings).
// Scores and player stats are random but realistic for junior T20. Semi-final and final teams
// are filled in from the points table / semi-final winners once those are known.
// Matches that already have a row in Results are never replayed, so it is safe to run again.
function simulateTournament({ fixtures, squads, results, upTo, rng = Math.random, parseDate }) {
  const has = v => v !== undefined && v !== null && String(v).trim() !== '';
  const num = v => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
  const toBalls = o => { const [a, b] = String(o ?? '0').split('.'); return num(a) * 6 + num(b || 0); };
  const ov = b => (b % 6 ? `${Math.floor(b / 6)}.${b % 6}` : String(b / 6));
  const rint = (a, b) => a + Math.floor(rng() * (b - a + 1));
  const split = (total, n) => {
    const w = Array.from({ length: n }, () => rng() ** 1.6 + 0.01); const s = w.reduce((x, y) => x + y, 0);
    const out = w.map(x => Math.floor(total * x / s)); out[0] += total - out.reduce((x, y) => x + y, 0); return out;
  };

  const squadOf = Object.fromEntries(squads.map(s => [s['Team'], String(s['Players'] || '').split(',').map(p => p.trim()).filter(Boolean)]));
  const groupOf = Object.fromEntries(squads.map(s => [s['Team'], String(s['Group'] || '')]));
  const fx = fixtures.filter(f => has(f['Match No'])).map(f => ({ ...f }));
  const done = new Map(results.filter(r => has(r['Match No']) && (has(r['Winner']) || has(r['Result']))).map(r => [String(r['Match No']), r]));
  const isLeague = f => /league/i.test(f['Stage'] || 'League');

  const standings = () => {
    const t = {};
    for (const s of squads) t[s['Team']] = { team: s['Team'], group: groupOf[s['Team']], pts: 0, w: 0, rf: 0, bf: 0, ra: 0, bb: 0 };
    for (const f of fx.filter(isLeague)) {
      const r = done.get(String(f['Match No'])); if (!r) continue;
      const A = t[f['Team A']], B = t[f['Team B']]; if (!A || !B) continue;
      const res = String(r['Result'] || '').toLowerCase();
      if (res.includes('no result') || res.includes('abandon')) { A.pts++; B.pts++; continue; }
      if (res.includes('tie')) { A.pts++; B.pts++; }
      else if (r['Winner'] === f['Team A']) { A.pts += 2; A.w++; } else { B.pts += 2; B.w++; }
      const ab = num(r['Team A Wickets']) >= 10 ? 120 : toBalls(r['Team A Overs']);
      const bb = num(r['Team B Wickets']) >= 10 ? 120 : toBalls(r['Team B Overs']);
      A.rf += num(r['Team A Runs']); A.bf += ab; A.ra += num(r['Team B Runs']); A.bb += bb;
      B.rf += num(r['Team B Runs']); B.bf += bb; B.ra += num(r['Team A Runs']); B.bb += ab;
    }
    const nrr = x => (x.bf && x.bb ? x.rf / (x.bf / 6) - x.ra / (x.bb / 6) : 0);
    const by = {};
    for (const x of Object.values(t)) (by[x.group] ??= []).push(x);
    for (const g in by) by[g].sort((x, y) => y.pts - x.pts || nrr(y) - nrr(x) || y.w - x.w);
    return by;
  };

  // Fill knockout placeholders like "Group A Winner", "Group B Runner-up", "Winner SF1"
  const resolve = name => {
    let m = /^group\s+(\w+)\s+(winner|runner-?up)$/i.exec(String(name).trim());
    if (m) {
      if (fx.some(f => isLeague(f) && !done.has(String(f['Match No'])))) return null;
      const g = standings()[m[1].toUpperCase()] || []; return (g[/winner/i.test(m[2]) ? 0 : 1] || {}).team || null;
    }
    m = /^winner\s+sf\s*(\d)$/i.exec(String(name).trim());
    if (m) {
      const sf = fx.find(f => new RegExp(`semi\\s*final\\s*${m[1]}`, 'i').test(f['Stage'] || ''));
      const r = sf && done.get(String(sf['Match No'])); return r ? r['Winner'] : null;
    }
    return squadOf[name] ? name : null;
  };

  const innings = (no, bat, bowl, runs, wkts, balls, out) => {
    const batters = squadOf[bat], bowlers = squadOf[bowl].slice(-5);
    const nbat = Math.min(batters.length, wkts + 2);
    // batting: runs split across batters, balls follow a realistic strike rate (90-170)
    const br = split(Math.max(0, runs - rint(4, 12)), nbat);
    batters.slice(0, nbat).forEach((p, i) => {
      const r = Math.max(0, br[i]), six = Math.floor(r / 18), four = Math.floor((r - six * 6) / 9);
      const bl = Math.max(1, Math.round(r / (0.9 + rng() * 0.8)) || rint(1, 4));
      add(out, no, p, bat, { Runs: r, Balls: bl, Fours: four, Sixes: six });
    });
    // bowling: max 4 overs each, runs conceded roughly by balls bowled, wickets dealt one at a time
    const per = [24, 24, 24, 24, 24]; let left = 120 - balls, j = 4;
    while (left > 0) { const tk = Math.min(left, per[j]); per[j] -= tk; left -= tk; j--; }
    const wt = per.map(b => b * (0.6 + rng() * 0.8)), wsum = wt.reduce((x, y) => x + y, 0);
    const conc = wt.map(x => Math.round(runs * x / wsum)); conc[0] += runs - conc.reduce((x, y) => x + y, 0);
    const wk = [0, 0, 0, 0, 0];
    for (let i = 0; i < Math.min(wkts, 9 + (wkts > 9)); i++) { let k; do { k = rint(0, 4); } while (!per[k]); wk[k]++; }
    bowlers.forEach((p, i) => { if (per[i]) add(out, no, p, bowl, { 'Overs Bowled': ov(per[i]), 'Runs Conceded': Math.max(0, conc[i]), Wickets: wk[i] }); });
    for (let i = 0, n = Math.min(wkts, rint(2, 5)); i < n; i++) add(out, no, squadOf[bowl][rint(0, squadOf[bowl].length - 1)], bowl, { Catches: 1 }, true);
  };
  const add = (out, no, player, team, vals, sum) => {
    const k = `${no}|${player}`;
    const row = out.get(k) || { 'Match No': no, Player: player, Team: team, Runs: '', Balls: '', Fours: '', Sixes: '', 'Overs Bowled': '', 'Runs Conceded': '', Wickets: '', Catches: '' };
    for (const [c, v] of Object.entries(vals)) row[c] = sum ? num(row[c]) + v : v;
    out.set(k, row);
  };

  const newResults = [], newStats = [], fixtureUpdates = [], log = [];
  const due = fx.filter(f => !done.has(String(f['Match No'])) && parseDate(f['Date']) <= upTo)
                .sort((x, y) => parseDate(x['Date']) - parseDate(y['Date']) || num(x['Match No']) - num(y['Match No']));
  for (const f of due) {
    const no = f['Match No'];
    const a = resolve(f['Team A']), b = resolve(f['Team B']);
    if (!a || !b) { log.push(`Match ${no}: teams not decided yet (${f['Team A']} vs ${f['Team B']}), skipped`); continue; }
    if (a !== f['Team A'] || b !== f['Team B']) {
      f['Team A'] = a; f['Team B'] = b;
      fixtureUpdates.push({ 'Match No': no, 'Team A': a, 'Team B': b });
    }
    const first = rng() < 0.5 ? a : b, second = first === a ? b : a;
    const r1 = rint(125, 195), w1 = rint(3, 9);
    let r2, w2, b2, winner;
    const roll = rng();
    if (roll < 0.02) { r2 = r1; w2 = rint(5, 9); b2 = 120; winner = ''; }          // rare tie
    else if (roll < 0.51) { r2 = r1 + rint(1, 6); w2 = rint(2, 8); b2 = rint(96, 119); winner = second; }
    else { w2 = rng() < 0.4 ? 10 : rint(6, 9); r2 = r1 - rint(3, 45); b2 = w2 === 10 ? rint(100, 119) : 120; winner = first; }
    if (!isLeague(f) && !winner) winner = rng() < 0.5 ? a : b; // knockout tie decided by a Super Over
    const sc = { [first]: [r1, w1, 120], [second]: [r2, w2, b2] };
    const out = new Map();
    innings(no, first, second, r1, w1, 120, out);
    innings(no, second, first, r2, w2, b2, out);
    const rows = [...out.values()];
    const pomPool = rows.filter(x => x.Team === (winner || first));
    const pom = pomPool.sort((x, y) => (num(y.Runs) + 20 * num(y.Wickets)) - (num(x.Runs) + 20 * num(x.Wickets)))[0].Player;
    const tie = !winner || (r1 === r2);
    const res = {
      'Match No': no, 'Batted First': first,
      'Team A Runs': sc[a][0], 'Team A Wickets': sc[a][1], 'Team A Overs': ov(sc[a][2]),
      'Team B Runs': sc[b][0], 'Team B Wickets': sc[b][1], 'Team B Overs': ov(sc[b][2]),
      Result: tie ? (isLeague(f) ? 'Tie' : 'Tie (won Super Over)') : 'Normal',
      Winner: winner, 'Player of the Match': pom,
    };
    done.set(String(no), res);
    newResults.push(res); newStats.push(...rows);
    log.push(`Match ${no} (${f['Date']}, ${f['Stage'] || 'League'}): ${a} ${sc[a][0]}/${sc[a][1]} vs ${b} ${sc[b][0]}/${sc[b][1]} -> ${winner || 'tie'}`);
  }
  return { newResults, newStats, fixtureUpdates, log };
}

const settings = $('Simulation Settings').first().json;
const rows = name => $(name).all().map(i => i.json || {}).filter(r => Object.keys(r).length);
const parseDate = s => {
  const str = String(s ?? '').trim();
  let d = DateTime.fromFormat(str, 'dd LLL yyyy');
  if (!d.isValid) d = DateTime.fromISO(str);
  if (!d.isValid) d = DateTime.fromJSDate(new Date(str));
  return d.isValid ? d.toMillis() : Infinity;
};
const out = simulateTournament({
  fixtures: rows('Read Fixtures'), squads: rows('Read Squads'), results: rows('Read Results'),
  upTo: parseDate(settings.simulateUpTo), parseDate,
});
return [{ json: { simulatedUpTo: settings.simulateUpTo, matchesPlayed: out.newResults.length, log: out.log, ...out } }];
